"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  GlowRules,
  type GlowRulesHandle,
} from "@/components/bjork-ui/misc/glow-rules";
import { MediaStage } from "@/components/bjork-ui/galleries/project-index-media";
import {
  BJORK_PALETTE,
  type BjorkTone,
} from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { useVisibleLoop } from "@/components/bjork-ui/_core/loop";
import { ease, springs } from "@/components/bjork-ui/_core/motion";
import { cn } from "@/lib/utils";

/* ------------------------------------------------------------------------------------------------
 * Types
 * ---------------------------------------------------------------------------------------------- */

export interface ProjectIndexMedia {
  type: "image" | "video";
  src: string;
  /** Still frame for videos. Shown until the first frame decodes, and instead of the video under reduced motion. */
  poster?: string;
  alt: string;
  /** Focal point for cover cropping, 0 to 1 from the top-left. Default [0.5, 0.5]. */
  focal?: [number, number];
}

export interface ProjectIndexItem {
  id: string;
  title: string;
  href: string;
  client?: string;
  year: number | string;
  /** What you did. The headline of the card. */
  role: string;
  services: string[];
  /** One true number about the work. Leave it out rather than invent one. */
  outcome?: { value: string; label: string };
  category?: { label: string; color?: string };
  media: ProjectIndexMedia;
  /** Tints the row slab and index. Defaults to the index accent. */
  accent?: string;
  disabled?: boolean;
}

export interface ProjectIndexProps {
  items: ProjectIndexItem[];
  heading?: ReactNode;
  tone?: BjorkTone;
  /** Accent for every row without its own. */
  accent?: string;
  /** `corner` docks the card at the bottom right; `follow` lets it lean toward the hovered row. */
  cardPlacement?: "corner" | "follow";
  /** `dissolve` is a WebGL grain dissolve; it falls back to `crossfade` without WebGL. */
  mediaTransition?: "dissolve" | "crossfade" | "none";
  /** Hover time before the card rises, in ms. Default 90. */
  dwellMs?: number;
  /** `auto` uses the expanding list on touch screens and under 900 px. */
  layout?: "auto" | "hover" | "expand";
  showIndexNumbers?: boolean;
  /** Show the item count beside the heading. Default true. */
  showCount?: boolean;
  /** Label of the card's call to action. Default "Open project". */
  openLabel?: string;
  /** Opens links in a new tab. */
  target?: "_self" | "_blank";
  renderRowEnd?: (item: ProjectIndexItem, active: boolean) => ReactNode;
  renderCardBody?: (item: ProjectIndexItem) => ReactNode;
  renderCardFooter?: (item: ProjectIndexItem) => ReactNode;
  onActiveChange?: (item: ProjectIndexItem | null) => void;
  /** Opens the card on this item at mount, as if it were hovered. Useful for previews and pinned states. */
  defaultActiveId?: string;
  className?: string;
}

/* ------------------------------------------------------------------------------------------------
 * Tokens
 * ---------------------------------------------------------------------------------------------- */

const ROW_H = 72;
const EASE_OUT = "cubic-bezier(0.23,1,0.32,1)";
const SPEED_GATE = 1.5; // px per ms
const SETTLE_MS = 60;
const GRACE_MS = 160;

function tokens(tone: BjorkTone) {
  const p = BJORK_PALETTE[tone];
  const dark = tone === "dark";
  return {
    dark,
    text: p.text,
    // Titles dim to these when another row is active. Both stay above 4.5:1 on the index background.
    dim: dark ? 0.56 : 0.66,
    meta: dark ? "rgba(237,237,237,0.6)" : "rgba(23,23,23,0.64)",
    faint: dark ? "rgba(237,237,237,0.42)" : "rgba(23,23,23,0.5)",
    hair: dark ? "rgba(255,255,255,0.1)" : "rgba(23,23,23,0.1)",
    card: dark ? "rgba(18,18,20,0.86)" : "rgba(255,252,246,0.9)",
    cardBorder: dark ? "rgba(255,255,255,0.08)" : "rgba(23,23,23,0.08)",
    cardShadow: dark
      ? "0 40px 90px -20px rgba(0,0,0,0.75), 0 12px 24px -12px rgba(0,0,0,0.5)"
      : "0 30px 60px -24px rgba(66,52,33,0.28), 0 10px 20px -12px rgba(66,52,33,0.16)",
    inner: dark
      ? "inset 0 1px 0 rgba(255,255,255,0.06)"
      : "inset 0 1px 0 rgba(255,255,255,0.9)",
    mediaBg: dark ? "#0d0d0e" : "#ece6da",
    accent: p.accent,
    accentInk: p.accentInk,
    glow: dark ? "#ffffff" : "#5b3f22",
  };
}
type Tokens = ReturnType<typeof tokens>;

/** Accent as ink: on light backgrounds, darken it so small text keeps its contrast. */
function inkFor(accent: string, t: Tokens) {
  return t.dark
    ? `color-mix(in oklab, ${accent} 58%, #ffffff)`
    : `color-mix(in oklab, ${accent} 62%, #1a120c)`;
}

/* ------------------------------------------------------------------------------------------------
 * Hooks
 * ---------------------------------------------------------------------------------------------- */

function useMedia(query: string, server = false) {
  return useSyncExternalStore(
    (cb) => {
      if (typeof window === "undefined") return () => {};
      const mq = window.matchMedia(query);
      mq.addEventListener("change", cb);
      return () => mq.removeEventListener("change", cb);
    },
    () => window.matchMedia(query).matches,
    () => server,
  );
}

const REDUCED = "(prefers-reduced-motion: reduce)";

/* ------------------------------------------------------------------------------------------------
 * Small parts
 * ---------------------------------------------------------------------------------------------- */

function pad(n: number) {
  return String(n).padStart(2, "0");
}

/** A field that swaps its value in place. Only changed values move; the old one leaves as the new one arrives. */
function Swap({
  value,
  dir,
  delay,
  intro,
  reduce,
  className,
  style,
  children,
}: {
  value: string;
  dir: number;
  delay: number;
  intro: boolean;
  reduce: boolean;
  className?: string;
  style?: CSSProperties;
  children: ReactNode;
}) {
  const from = reduce
    ? { opacity: 0 }
    : intro
      ? { opacity: 0, y: 8, filter: "blur(4px)" }
      : { opacity: 0, y: 6 * dir, filter: "blur(0px)" };
  return (
    <span className={cn("grid", className)} style={style}>
      <AnimatePresence initial={true}>
        <motion.span
          key={value}
          className="col-start-1 row-start-1 block min-w-0"
          initial={from}
          animate={{
            opacity: 1,
            y: 0,
            filter: "blur(0px)",
            transition: reduce
              ? { duration: 0.15 }
              : {
                  duration: intro ? 0.26 : 0.22,
                  delay: delay / 1000,
                  ease: ease.out,
                },
          }}
          exit={{
            opacity: 0,
            y: reduce ? 0 : -6 * dir,
            transition: { duration: 0.12, ease: ease.out },
          }}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

/** Characters roll vertically when they change, in the direction of travel. */
function Roll({
  value,
  dir,
  reduce,
}: {
  value: string;
  dir: number;
  reduce: boolean;
}) {
  const chars = value.split("");
  return (
    <span className="inline-flex tabular-nums" aria-hidden>
      {chars.map((c, i) => (
        <span
          key={i}
          className="relative inline-grid overflow-hidden"
          style={{ height: "1em", lineHeight: 1 }}
        >
          <AnimatePresence initial={false}>
            <motion.span
              key={c}
              className="col-start-1 row-start-1 block"
              initial={reduce ? false : { y: `${dir > 0 ? 100 : -100}%` }}
              animate={{
                y: "0%",
                transition: { duration: 0.42, delay: i * 0.03, ease: ease.out },
              }}
              exit={{
                y: `${dir > 0 ? -100 : 100}%`,
                transition: { duration: 0.42, delay: i * 0.03, ease: ease.out },
              }}
            >
              {c === " " ? " " : c}
            </motion.span>
          </AnimatePresence>
        </span>
      ))}
    </span>
  );
}

function CategoryMark({
  category,
  t,
}: {
  category?: ProjectIndexItem["category"];
  t: Tokens;
}) {
  if (!category) return null;
  return (
    <span className="inline-flex items-center gap-2">
      <span
        aria-hidden
        className="size-1.5 shrink-0 rounded-full"
        style={{ background: category.color ?? t.faint }}
      />
      <span>{category.label}</span>
    </span>
  );
}

/** Stacked stills for the crossfade mode, and the reduced-motion path. Videos play only while active. */
function DomMedia({
  items,
  index,
  reduce,
  mode,
  open,
}: {
  items: ProjectIndexItem[];
  index: number;
  reduce: boolean;
  mode: "crossfade" | "none";
  open: boolean;
}) {
  const ms = mode === "none" ? 0 : reduce ? 150 : 300;
  return (
    <>
      {items.map((item, i) => {
        const m = item.media;
        const active = i === index;
        const still = m.type === "image" ? m.src : m.poster;
        const pos = `${(m.focal?.[0] ?? 0.5) * 100}% ${(m.focal?.[1] ?? 0.5) * 100}%`;
        return (
          <div
            key={item.id}
            className="absolute inset-0"
            style={{
              opacity: active ? 1 : 0,
              transform: active || reduce ? "scale(1)" : "scale(1.04)",
              transition: `opacity ${ms}ms ${EASE_OUT}, transform ${ms}ms ${EASE_OUT}`,
              zIndex: active ? 1 : 0,
            }}
          >
            {still && (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={still}
                alt=""
                className="size-full object-cover"
                style={{ objectPosition: pos }}
                decoding="async"
              />
            )}
            {m.type === "video" && active && open && !reduce && (
              <video
                src={m.src}
                poster={m.poster}
                muted
                loop
                playsInline
                autoPlay
                className="absolute inset-0 size-full object-cover"
                style={{ objectPosition: pos }}
              />
            )}
          </div>
        );
      })}
    </>
  );
}

/* ------------------------------------------------------------------------------------------------
 * Hover layout
 * ---------------------------------------------------------------------------------------------- */

interface CardState {
  open: boolean;
  index: number;
  /** Content changes since the card opened. 0 means the fields play their rise. */
  changes: number;
  dir: number;
  /** Bumps on every open so the fields remount and rise again. */
  openId: number;
}

function HoverIndex(props: ProjectIndexProps & { t: Tokens; reduce: boolean }) {
  const {
    items,
    t,
    reduce,
    accent,
    cardPlacement = "corner",
    mediaTransition = "dissolve",
    dwellMs = 90,
    showIndexNumbers = true,
    openLabel = "Open project",
    target,
    renderRowEnd,
    renderCardBody,
    renderCardFooter,
    onActiveChange,
    defaultActiveId,
  } = props;

  const defaultIndex = defaultActiveId
    ? items.findIndex((x) => x.id === defaultActiveId)
    : -1;
  const uid = useId();
  const wrapRef = useRef<HTMLDivElement>(null);
  const glowRef = useRef<GlowRulesHandle>(null);
  const rowRefs = useRef<(HTMLLIElement | null)[]>([]);
  const linkRefs = useRef<(HTMLAnchorElement | null)[]>([]);
  const endRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const cardDockRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mediaBoxRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<MediaStage | null>(null);

  const [hover, setHover] = useState(defaultIndex);
  // Where the slab sits. It keeps its row while fading out, and appears in place (jump) when nothing was active.
  const [slab, setSlab] = useState({
    index: Math.max(0, defaultIndex),
    jump: true,
  });
  const [focusIndex, setFocusIndex] = useState(Math.max(0, defaultIndex));
  const [card, setCard] = useState<CardState>({
    open: defaultIndex >= 0,
    index: Math.max(0, defaultIndex),
    changes: 0,
    dir: 1,
    openId: defaultIndex >= 0 ? 1 : 0,
  });
  const [geom, setGeom] = useState({
    width: 0,
    rowTops: [] as number[],
    rowH: ROW_H,
  });
  const [stageOk, setStageOk] = useState<boolean | null>(null);

  // Live copies for event handlers.
  const live = useRef({
    hover: defaultIndex,
    hoverStart: 0,
    lastFastAt: 0,
    lastMove: { x: 0, y: 0, t: 0 },
    speed: 0,
    gate: 0 as ReturnType<typeof setTimeout> | 0,
    grace: 0 as ReturnType<typeof setTimeout> | 0,
    card,
    pointerY: 0,
  });
  useEffect(() => {
    live.current.card = card;
  }, [card]);

  const useShader =
    mediaTransition === "dissolve" && !reduce && stageOk !== false;
  const domMode: "crossfade" | "none" =
    mediaTransition === "none" ? "none" : "crossfade";

  /* Geometry ----------------------------------------------------------------------------------- */

  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const read = () => {
      const width = wrap.clientWidth;
      const rowTops = rowRefs.current.map((r) => r?.offsetTop ?? 0);
      const rowH = rowRefs.current[0]?.offsetHeight ?? ROW_H;
      setGeom((g) =>
        g.width === width &&
        g.rowH === rowH &&
        g.rowTops.join() === rowTops.join()
          ? g
          : { width, rowTops, rowH },
      );
    };
    const ro = new ResizeObserver(read);
    ro.observe(wrap);
    read();
    return () => ro.disconnect();
  }, [items.length]);

  const cardW = Math.round(Math.min(400, Math.max(300, geom.width * 0.34)));
  const inset = 16;

  // A default active row also gets its light, as if the pointer rested on it.
  useEffect(() => {
    if (defaultIndex < 0) return;
    const raf = requestAnimationFrame(() => {
      const row = rowRefs.current[defaultIndex];
      if (row)
        glowRef.current?.pointAt(
          Math.min(row.offsetWidth * 0.3, 320),
          row.offsetTop + row.offsetHeight / 2,
        );
    });
    return () => cancelAnimationFrame(raf);
    // Mount only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* Media stage -------------------------------------------------------------------------------- */

  const loop = useVisibleLoop(
    wrapRef,
    () => {
      const stage = stageRef.current;
      if (!stage) return false;
      return stage.frame(performance.now());
    },
    { enabled: useShader },
  );

  useEffect(() => {
    if (mediaTransition !== "dissolve" || reduce) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const stage = MediaStage.create(canvas);
    stageRef.current = stage;
    // Reporting the result is the point of this effect: it decides between the canvas and the DOM stack.
    setStageOk(!!stage);
    if (!stage) return;
    const box = mediaBoxRef.current;
    const ro = new ResizeObserver(() => {
      if (!box) return;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      stage.resize(
        Math.round(box.clientWidth * dpr),
        Math.round(box.clientHeight * dpr),
      );
      loop.wake();
    });
    if (box) ro.observe(box);
    // Warm every still so the first rise never shows an empty frame.
    items.forEach((it) => stage.preload(it.media));
    const c = live.current.card;
    if (c.open && items[c.index])
      stage.show(items[c.index].media, 1, true).then(() => loop.wake());
    const onVis = () => {
      if (document.visibilityState === "hidden") stage.pauseVideos();
      else if (live.current.card.open) stage.resumeVideo();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      ro.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      stage.dispose();
      stageRef.current = null;
    };
    // items identity changes should not rebuild the GL context; media is looked up by index at show time.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mediaTransition, reduce, loop]);

  const showMedia = useCallback(
    (index: number, dir: number, instant: boolean) => {
      const stage = stageRef.current;
      const item = items[index];
      if (!stage || !item) return;
      stage.show(item.media, dir, instant).then(() => loop.wake());
      loop.wake();
    },
    [items, loop],
  );

  /* Card control ------------------------------------------------------------------------------- */

  const emit = useCallback(
    (item: ProjectIndexItem | null) => {
      onActiveChange?.(item);
    },
    [onActiveChange],
  );

  const openCard = useCallback(
    (index: number) => {
      const c = live.current.card;
      if (c.open && c.index === index) return;
      const dir = c.open ? Math.sign(index - c.index) || 1 : 1;
      const next: CardState = c.open
        ? { ...c, index, dir, changes: c.changes + 1 }
        : { open: true, index, dir: 1, changes: 0, openId: c.openId + 1 };
      live.current.card = next;
      setCard(next);
      showMedia(index, dir, !c.open);
      emit(items[index] ?? null);
    },
    [emit, items, showMedia],
  );

  const closeCard = useCallback(() => {
    const c = live.current.card;
    if (!c.open) return;
    const next = { ...c, open: false };
    live.current.card = next;
    setCard(next);
    emit(null);
    // Let the sink finish before stopping video.
    setTimeout(() => {
      if (!live.current.card.open) stageRef.current?.pauseVideos();
    }, 320);
  }, [emit]);

  const clearGate = () => {
    const l = live.current;
    if (l.gate) clearTimeout(l.gate);
    l.gate = 0;
  };

  const evaluateRef = useRef<() => void>(() => {});
  // The gate: the card rises only after the dwell, and only once the pointer has slowed down.
  // While open, content follows the same speed gate with a shorter dwell, so fast sweeps never flash.
  const evaluate = useCallback(() => {
    const l = live.current;
    l.gate = 0;
    const target = l.hover;
    if (target < 0 || items[target]?.disabled) return;
    const now = performance.now();
    const settled = now - l.lastFastAt >= SETTLE_MS;
    const c = l.card;
    const dwell = c.open ? Math.min(60, dwellMs) : dwellMs;
    if (c.open && c.index === target) return;
    if (now - l.hoverStart >= dwell && settled) {
      openCard(target);
      return;
    }
    l.gate = setTimeout(() => evaluateRef.current(), 16);
  }, [dwellMs, items, openCard]);
  useEffect(() => {
    evaluateRef.current = evaluate;
  }, [evaluate]);

  const enterRow = useCallback(
    (i: number) => {
      const l = live.current;
      if (l.grace) {
        clearTimeout(l.grace);
        l.grace = 0;
      }
      if (l.hover === i) return;
      setSlab({ index: i, jump: l.hover < 0 });
      l.hover = i;
      l.hoverStart = performance.now();
      setHover(i);
      clearGate();
      evaluate();
    },
    [evaluate],
  );

  const leaveList = useCallback(() => {
    const l = live.current;
    clearGate();
    l.hover = -1;
    setHover(-1);
    if (l.grace) clearTimeout(l.grace);
    l.grace = setTimeout(() => {
      l.grace = 0;
      closeCard();
    }, GRACE_MS);
  }, [closeCard]);

  useEffect(() => {
    const l = live.current;
    return () => {
      if (l.gate) clearTimeout(l.gate);
      if (l.grace) clearTimeout(l.grace);
    };
  }, []);

  /* Rows under the card fade their row ends so nothing reads through the glass. -------------- */

  useEffect(() => {
    const dock = cardDockRef.current;
    if (!card.open || !dock) {
      endRefs.current.forEach((el) => el?.removeAttribute("data-covered"));
      return;
    }
    let raf = 0;
    const update = () => {
      raf = 0;
      const r = dock.getBoundingClientRect();
      rowRefs.current.forEach((row, i) => {
        const end = endRefs.current[i];
        if (!row || !end) return;
        const b = row.getBoundingClientRect();
        const covered = b.bottom > r.top + 4 && b.top < r.bottom - 4;
        if (covered) end.setAttribute("data-covered", "");
        else end.removeAttribute("data-covered");
      });
    };
    const schedule = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    update();
    window.addEventListener("scroll", schedule, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", schedule);
    return () => {
      if (raf) cancelAnimationFrame(raf);
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
    };
  }, [card.open, geom]);

  /* Keyboard ----------------------------------------------------------------------------------- */

  const focusRow = (i: number) => {
    const n = items.length;
    const next = (i + n) % n;
    linkRefs.current[next]?.focus();
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLUListElement>) => {
    const current = linkRefs.current.findIndex(
      (el) => el === document.activeElement,
    );
    if (current < 0) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      focusRow(current + 1);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      focusRow(current - 1);
    } else if (e.key === "Home") {
      e.preventDefault();
      focusRow(0);
    } else if (e.key === "End") {
      e.preventDefault();
      focusRow(items.length - 1);
    } else if (e.key === "Escape") {
      if (live.current.card.open) {
        e.preventDefault();
        closeCard();
      }
    }
  };

  /* Derived ------------------------------------------------------------------------------------ */

  const activeIndex = hover;
  const cardItem = items[card.index];
  const accentOf = (item?: ProjectIndexItem) =>
    item?.accent ?? accent ?? t.accent;
  const slabAccent = accentOf(items[slab.index]);
  const slabY = geom.rowTops[slab.index] ?? 0;

  const tether =
    card.open && !reduce && geom.width > 0
      ? {
          x: geom.width - inset - cardW - 24,
          y: (geom.rowTops[card.index] ?? 0) + geom.rowH / 2,
          width: Math.max(220, geom.width * 0.32),
          height: geom.rowH * 0.62,
          intensity: t.dark ? 0.55 : 0.5,
        }
      : null;

  // Follow mode: the card leans toward the hovered row, a few px at most.
  const followY = (() => {
    if (cardPlacement !== "follow" || !card.open || reduce) return 0;
    const rows = geom.rowTops.length;
    if (!rows) return 0;
    const centre = (rows - 1) / 2;
    return Math.max(-24, Math.min(24, (card.index - centre) * 6));
  })();

  const describe = (item: ProjectIndexItem) =>
    [
      item.role,
      item.services.join(", "),
      item.client,
      String(item.year),
      item.outcome ? `${item.outcome.value} ${item.outcome.label}` : "",
    ]
      .filter(Boolean)
      .join(". ");

  return (
    <div
      ref={wrapRef}
      className="relative"
      onPointerMove={(e) => {
        if (e.pointerType === "touch") return;
        const l = live.current;
        const now = performance.now();
        const dt = now - l.lastMove.t;
        if (dt > 0 && dt < 100) {
          const v =
            Math.hypot(e.clientX - l.lastMove.x, e.clientY - l.lastMove.y) / dt;
          l.speed = l.speed * 0.6 + v * 0.4;
          if (l.speed > SPEED_GATE) l.lastFastAt = now;
        }
        l.lastMove = { x: e.clientX, y: e.clientY, t: now };
      }}
      onPointerLeave={(e) => {
        if (e.pointerType === "touch") return;
        leaveList();
      }}
    >
      <GlowRules
        ref={glowRef}
        selector="[data-pi-row]"
        tone={t.dark ? "dark" : "light"}
        color={t.glow}
        ruleColor={t.hair}
        radius={[0.4, 100]}
        lerp={0.12}
        quantize={4}
        tether={tether}
        drawIn
      >
        {/* The slab: one element that travels between rows. */}
        <motion.div
          aria-hidden
          className="pointer-events-none absolute inset-x-0 top-0"
          style={{ height: geom.rowH, zIndex: 0 }}
          initial={false}
          animate={{ y: slabY, opacity: activeIndex >= 0 ? 1 : 0 }}
          transition={{
            y: reduce || slab.jump ? { duration: 0 } : springs.snappy,
            opacity: {
              duration: activeIndex >= 0 ? 0.12 : 0.2,
              ease: "easeOut",
            },
          }}
        >
          <div
            className="absolute inset-0"
            style={{
              backgroundColor: `color-mix(in srgb, ${slabAccent} ${t.dark ? 14 : 10}%, transparent)`,
              WebkitMaskImage:
                "linear-gradient(90deg, #000 0%, rgba(0,0,0,0.5) 30%, transparent 72%)",
              maskImage:
                "linear-gradient(90deg, #000 0%, rgba(0,0,0,0.5) 30%, transparent 72%)",
              transition: slab.jump ? "none" : "background-color 220ms ease",
            }}
          />
          <div
            className="absolute bottom-[1px] left-0 top-[1px] w-[2px] origin-center"
            style={{
              background: slabAccent,
              transform: `scaleY(${activeIndex >= 0 ? 1 : 0})`,
              transition: `transform 180ms ${EASE_OUT}${slab.jump ? "" : ", background-color 220ms ease"}`,
            }}
          />
        </motion.div>

        <ul
          role="list"
          className="relative m-0 list-none p-0"
          style={{ zIndex: 0 }}
          onKeyDown={onKeyDown}
        >
          {items.map((item, i) => {
            const active = i === activeIndex;
            const dimmed = activeIndex >= 0 && !active;
            const descId = `${uid}-d${i}`;
            const ink = inkFor(accentOf(item), t);
            return (
              <motion.li
                key={item.id}
                ref={(el) => {
                  rowRefs.current[i] = el;
                }}
                data-pi-row=""
                className="relative"
                initial={reduce ? { opacity: 0 } : { opacity: 0, y: 24 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "0px 0px -8% 0px" }}
                transition={{
                  duration: reduce ? 0.2 : 0.6,
                  delay: reduce ? 0 : i * 0.04,
                  ease: ease.out,
                }}
              >
                <a
                  ref={(el) => {
                    linkRefs.current[i] = el;
                  }}
                  href={item.disabled ? undefined : item.href}
                  target={target}
                  rel={target === "_blank" ? "noreferrer" : undefined}
                  aria-disabled={item.disabled || undefined}
                  aria-describedby={descId}
                  tabIndex={i === focusIndex ? 0 : -1}
                  className={cn(
                    "group/row relative grid items-center px-4 no-underline outline-none",
                    "rounded-[2px] focus-visible:shadow-[inset_0_0_0_1px_var(--pi-ring)]",
                    item.disabled ? "cursor-default" : "cursor-pointer",
                  )}
                  style={
                    {
                      height: ROW_H,
                      gridTemplateColumns: showIndexNumbers
                        ? "48px minmax(0,1fr) auto"
                        : "minmax(0,1fr) auto",
                      color: t.text,
                      "--pi-ring": `color-mix(in srgb, ${accentOf(item)} 45%, transparent)`,
                    } as CSSProperties
                  }
                  onPointerEnter={(e) => {
                    if (e.pointerType === "touch") return;
                    enterRow(i);
                  }}
                  onFocus={(e) => {
                    setFocusIndex(i);
                    // Keyboard runs the same choreography, without the dwell.
                    if (!e.currentTarget.matches(":focus-visible")) return;
                    const l = live.current;
                    if (l.grace) {
                      clearTimeout(l.grace);
                      l.grace = 0;
                    }
                    clearGate();
                    setSlab({ index: i, jump: l.hover < 0 });
                    l.hover = i;
                    setHover(i);
                    if (!item.disabled) openCard(i);
                  }}
                  onBlur={(e) => {
                    const next = e.relatedTarget as Node | null;
                    if (next && wrapRef.current?.contains(next)) return;
                    leaveList();
                  }}
                  onClick={(e) => {
                    if (item.disabled) e.preventDefault();
                  }}
                >
                  {showIndexNumbers && (
                    <span
                      className="font-mono text-[12px] tabular-nums tracking-[0.02em]"
                      style={{
                        color: active ? ink : t.faint,
                        transition: "color 200ms ease",
                      }}
                    >
                      {pad(i + 1)}
                    </span>
                  )}
                  <span
                    className="truncate font-medium leading-none tracking-[-0.015em]"
                    style={{
                      fontSize: "clamp(20px, 2vw, 28px)",
                      opacity: dimmed ? t.dim : item.disabled ? t.dim : 1,
                      transform: `translate3d(${active && !reduce ? 12 : 0}px,0,0)`,
                      transition: `opacity 200ms ease, transform 220ms ${EASE_OUT}`,
                    }}
                  >
                    {item.title}
                  </span>
                  <span
                    ref={(el) => {
                      endRefs.current[i] = el;
                    }}
                    className="flex items-center gap-6 font-mono text-[12px] tabular-nums tracking-[0.02em] transition-opacity duration-200 data-[covered]:opacity-0"
                    style={{ color: t.meta }}
                  >
                    {renderRowEnd ? (
                      renderRowEnd(item, active)
                    ) : (
                      <>
                        <CategoryMark category={item.category} t={t} />
                        <span>{item.year}</span>
                      </>
                    )}
                  </span>
                  <span id={descId} className="sr-only">
                    {describe(item)}
                  </span>
                </a>
              </motion.li>
            );
          })}
        </ul>
      </GlowRules>

      {/* The dossier rail: a column on the right whose card docks at the bottom, and to the viewport bottom on long lists. */}
      <div
        aria-hidden
        className="pointer-events-none absolute bottom-0 top-0 flex flex-col justify-end"
        style={{ right: inset, width: cardW, zIndex: 2, paddingBottom: inset }}
      >
        <div ref={cardDockRef} className="sticky" style={{ bottom: 24 }}>
          <motion.div
            initial={false}
            animate={{ y: followY }}
            transition={{ type: "spring", stiffness: 170, damping: 26 }}
          >
            <Dossier
              card={card}
              item={cardItem}
              items={items}
              t={t}
              reduce={reduce}
              width={cardW}
              useShader={useShader}
              domMode={domMode}
              canvasRef={canvasRef}
              mediaBoxRef={mediaBoxRef}
              openLabel={openLabel}
              accent={accentOf(cardItem)}
              renderCardBody={renderCardBody}
              renderCardFooter={renderCardFooter}
            />
          </motion.div>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------------------------------------
 * The card
 * ---------------------------------------------------------------------------------------------- */

function Dossier({
  card,
  item,
  items,
  t,
  reduce,
  width,
  useShader,
  domMode,
  canvasRef,
  mediaBoxRef,
  openLabel,
  accent,
  renderCardBody,
  renderCardFooter,
}: {
  card: CardState;
  item?: ProjectIndexItem;
  items: ProjectIndexItem[];
  t: Tokens;
  reduce: boolean;
  width: number;
  useShader: boolean;
  domMode: "crossfade" | "none";
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  mediaBoxRef: React.RefObject<HTMLDivElement | null>;
  openLabel: string;
  accent: string;
  renderCardBody?: (item: ProjectIndexItem) => ReactNode;
  renderCardFooter?: (item: ProjectIndexItem) => ReactNode;
}) {
  const open = card.open;
  const intro = card.changes === 0;
  const dir = card.dir;
  const R = 14;

  // Rise: the card slides up out of a slot whose lower edge is the card's docked bottom edge,
  // so its top arrives first and the fields can follow top to bottom. It sinks back the same way.
  const shell = reduce
    ? {
        open: {
          opacity: 1,
          y: "0%",
          transition: { duration: 0.15, y: { duration: 0 } },
        },
        closed: {
          opacity: 0,
          y: "0%",
          transition: { duration: 0.15, y: { duration: 0 } },
        },
      }
    : {
        open: {
          opacity: 1,
          y: "0%",
          transition: { duration: 0.56, ease: ease.out },
        },
        closed: {
          opacity: 1,
          y: "101%",
          transition: { duration: 0.3, ease: ease.inOut },
        },
      };
  const shadow = {
    open: {
      opacity: 1,
      transition: {
        duration: reduce ? 0.15 : 0.5,
        ease: ease.out,
        delay: reduce ? 0 : 0.12,
      },
    },
    closed: {
      opacity: 0,
      transition: { duration: reduce ? 0.15 : 0.2, ease: ease.inOut },
    },
  };
  const zoom = {
    open: {
      scale: 1,
      transition: { duration: reduce ? 0 : 0.7, ease: ease.out },
    },
    closed: {
      scale: reduce ? 1 : 1.12,
      transition: { duration: 0, delay: 0.32 },
    },
  };
  const ink = inkFor(accent, t);
  const index = items.findIndex((x) => x.id === item?.id);

  const field = (k: number) => (intro ? 160 + k * 40 : k * 30);

  return (
    <motion.div
      className="relative"
      style={{ width }}
      initial="closed"
      animate={open ? "open" : "closed"}
    >
      {/* Shadow lives outside the clip so the rise does not crop it. */}
      <motion.div
        variants={shadow}
        className="absolute inset-0"
        style={{ borderRadius: R, boxShadow: t.cardShadow }}
      />
      {/* The slot. Its bottom edge is where the card docks; the card rises out of it. */}
      <div className="relative overflow-hidden" style={{ borderRadius: R }}>
        <motion.div
          variants={shell}
          className="relative overflow-hidden"
          style={{
            borderRadius: R,
            background: t.card,
            backdropFilter: "blur(14px) saturate(1.2)",
            WebkitBackdropFilter: "blur(14px) saturate(1.2)",
            boxShadow: `${t.inner}, inset 0 0 0 1px ${t.cardBorder}`,
            willChange: "transform",
          }}
        >
          <div className="p-[6px]">
            <div
              ref={mediaBoxRef}
              className="relative w-full overflow-hidden"
              style={{
                aspectRatio: "16 / 10",
                borderRadius: R - 6,
                background: t.mediaBg,
              }}
            >
              <motion.div variants={zoom} className="absolute inset-0">
                {useShader ? (
                  <canvas
                    ref={canvasRef}
                    className="absolute inset-0 size-full"
                  />
                ) : (
                  <DomMedia
                    items={items}
                    index={card.index}
                    reduce={reduce}
                    mode={domMode}
                    open={open}
                  />
                )}
              </motion.div>
              {/* Hairline inside the media edge, so light stills do not bleed into a light card. */}
              <div
                className="pointer-events-none absolute inset-0"
                style={{
                  borderRadius: R - 6,
                  boxShadow: `inset 0 0 0 1px ${t.dark ? "rgba(255,255,255,0.06)" : "rgba(23,23,23,0.06)"}`,
                }}
              />
            </div>
          </div>

          {item && (
            <div
              key={card.openId}
              className="px-4 pb-4 pt-3"
              style={{ color: t.text }}
            >
              {renderCardBody ? (
                renderCardBody(item)
              ) : (
                <>
                  <div
                    className="flex items-center justify-between font-mono text-[11px] uppercase tracking-[0.12em]"
                    style={{ color: t.meta }}
                  >
                    <Swap
                      value={`${item.client ?? item.category?.label ?? ""}·${item.year}`}
                      dir={dir}
                      delay={field(0)}
                      intro={intro}
                      reduce={reduce}
                      className="min-w-0"
                    >
                      <span className="flex min-w-0 items-center gap-2">
                        <span
                          aria-hidden
                          className="size-1.5 shrink-0 rounded-full"
                          style={{ background: item.category?.color ?? accent }}
                        />
                        <span className="truncate">
                          {item.client ?? item.category?.label}
                        </span>
                        <span aria-hidden style={{ color: t.faint }}>
                          /
                        </span>
                        <span className="tabular-nums">{item.year}</span>
                      </span>
                    </Swap>
                    <span className="tabular-nums" style={{ color: t.faint }}>
                      <Roll value={pad(index + 1)} dir={dir} reduce={reduce} />
                      <span className="px-[3px]">/</span>
                      {pad(items.length)}
                    </span>
                  </div>

                  <Swap
                    value={`t:${item.title}`}
                    dir={dir}
                    delay={field(1)}
                    intro={intro}
                    reduce={reduce}
                    className="mt-3"
                  >
                    <span className="block truncate text-[19px] font-medium leading-[1.15] tracking-[-0.015em]">
                      {item.title}
                    </span>
                  </Swap>
                  <Swap
                    value={`r:${item.role}`}
                    dir={dir}
                    delay={field(2)}
                    intro={intro}
                    reduce={reduce}
                    className="mt-1"
                  >
                    <span
                      className="block truncate text-[14px] leading-[1.3]"
                      style={{ color: t.meta }}
                    >
                      {item.role}
                    </span>
                  </Swap>

                  <Swap
                    value={`s:${item.services.join("|")}`}
                    dir={dir}
                    delay={field(3)}
                    intro={intro}
                    reduce={reduce}
                    className="mt-3"
                    style={{ minHeight: 36 }}
                  >
                    <span
                      className="line-clamp-2 text-[12.5px] leading-[18px]"
                      style={{ color: t.faint }}
                    >
                      {item.services.map((s, k) => (
                        <span key={s}>
                          {k > 0 && (
                            <span aria-hidden className="opacity-60">
                              {" \u2009/\u2009 "}
                            </span>
                          )}
                          <span
                            className="whitespace-nowrap"
                            style={{ color: t.meta }}
                          >
                            {s}
                          </span>
                        </span>
                      ))}
                    </span>
                  </Swap>

                  <div
                    className="mt-4 flex items-end justify-between gap-4 border-t pt-3"
                    style={{ borderColor: t.hair, minHeight: 52 }}
                  >
                    {renderCardFooter ? (
                      renderCardFooter(item)
                    ) : (
                      <>
                        <Swap
                          value={`o:${item.outcome?.value ?? ""}:${item.outcome?.label ?? ""}`}
                          dir={dir}
                          delay={field(4)}
                          intro={intro}
                          reduce={reduce}
                          className="min-w-0"
                        >
                          {item.outcome ? (
                            <span className="flex min-w-0 items-baseline gap-2">
                              <span
                                className="text-[28px] font-medium leading-none tracking-[-0.03em] tabular-nums"
                                style={{ color: t.text }}
                              >
                                {item.outcome.value}
                              </span>
                              <span
                                className="line-clamp-2 max-w-[150px] text-[12px] leading-[1.25]"
                                style={{ color: t.meta }}
                              >
                                {item.outcome.label}
                              </span>
                            </span>
                          ) : (
                            <span className="block h-[28px]" />
                          )}
                        </Swap>
                        <Swap
                          value="cta"
                          dir={dir}
                          delay={field(5)}
                          intro={intro}
                          reduce={reduce}
                          className="shrink-0"
                        >
                          <span
                            className="flex shrink-0 items-center gap-2 pb-[2px] text-[12px]"
                            style={{ color: ink }}
                          >
                            {openLabel}
                            <kbd
                              className="inline-grid h-[18px] min-w-[18px] place-items-center rounded-[5px] px-1 font-mono text-[10px] leading-none"
                              style={{
                                color: t.meta,
                                boxShadow: `inset 0 0 0 1px ${t.hair}`,
                              }}
                            >
                              ↵
                            </kbd>
                          </span>
                        </Swap>
                      </>
                    )}
                  </div>
                </>
              )}
            </div>
          )}
        </motion.div>
      </div>
    </motion.div>
  );
}

/* ------------------------------------------------------------------------------------------------
 * Expanding layout (touch and narrow screens)
 * ---------------------------------------------------------------------------------------------- */

function ExpandMedia({
  media,
  open,
  reduce,
  t,
}: {
  media: ProjectIndexMedia;
  open: boolean;
  reduce: boolean;
  t: Tokens;
}) {
  const ref = useRef<HTMLVideoElement>(null);
  useEffect(() => {
    const v = ref.current;
    if (!v) return;
    if (!open || reduce) {
      v.pause();
      return;
    }
    // Autoplay once most of the frame is on screen; pause when it scrolls away.
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.intersectionRatio >= 0.6) v.play().catch(() => {});
        else v.pause();
      },
      { threshold: [0, 0.6, 1] },
    );
    io.observe(v);
    return () => io.disconnect();
  }, [open, reduce]);

  const pos = `${(media.focal?.[0] ?? 0.5) * 100}% ${(media.focal?.[1] ?? 0.5) * 100}%`;
  return (
    <div
      className="relative w-full overflow-hidden rounded-[10px]"
      style={{ aspectRatio: "16 / 10", background: t.mediaBg }}
    >
      {media.type === "video" ? (
        <video
          ref={ref}
          src={open ? media.src : undefined}
          poster={media.poster}
          muted
          loop
          playsInline
          preload="none"
          controls={reduce}
          aria-label={media.alt}
          className="size-full object-cover"
          style={{ objectPosition: pos }}
        />
      ) : (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={media.src}
          alt={media.alt}
          loading="lazy"
          decoding="async"
          className="size-full object-cover"
          style={{ objectPosition: pos }}
        />
      )}
    </div>
  );
}

function ExpandIndex(
  props: ProjectIndexProps & { t: Tokens; reduce: boolean },
) {
  const {
    items,
    t,
    reduce,
    accent,
    showIndexNumbers = true,
    openLabel = "Open project",
    target,
    onActiveChange,
    renderCardBody,
  } = props;
  const uid = useId();
  const [openIndex, setOpenIndex] = useState(-1);
  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const toggle = (i: number) => {
    const next = openIndex === i ? -1 : i;
    setOpenIndex(next);
    onActiveChange?.(next >= 0 ? items[next] : null);
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLUListElement>) => {
    const current = btnRefs.current.findIndex(
      (el) => el === document.activeElement,
    );
    if (current < 0) return;
    const n = items.length;
    const go = (i: number) => btnRefs.current[(i + n) % n]?.focus();
    if (e.key === "ArrowDown") {
      e.preventDefault();
      go(current + 1);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      go(current - 1);
    } else if (e.key === "Home") {
      e.preventDefault();
      go(0);
    } else if (e.key === "End") {
      e.preventDefault();
      go(n - 1);
    } else if (e.key === "Escape" && openIndex >= 0) {
      e.preventDefault();
      setOpenIndex(-1);
      onActiveChange?.(null);
    }
  };

  return (
    <GlowRules
      selector="[data-pi-row]"
      tone={t.dark ? "dark" : "light"}
      ruleColor={t.hair}
      color={t.glow}
      drawIn
    >
      <ul role="list" className="m-0 list-none p-0" onKeyDown={onKeyDown}>
        {items.map((item, i) => {
          const open = i === openIndex;
          const panelId = `${uid}-p${i}`;
          const ink = inkFor(item.accent ?? accent ?? t.accent, t);
          return (
            <motion.li
              key={item.id}
              data-pi-row=""
              initial={reduce ? { opacity: 0 } : { opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{
                duration: reduce ? 0.2 : 0.5,
                delay: reduce ? 0 : i * 0.04,
                ease: ease.out,
              }}
            >
              <button
                ref={(el) => {
                  btnRefs.current[i] = el;
                }}
                type="button"
                aria-expanded={open}
                aria-controls={panelId}
                onClick={() => toggle(i)}
                className="grid w-full items-center gap-0 px-1 text-left outline-none focus-visible:rounded-[4px] focus-visible:shadow-[inset_0_0_0_1px_var(--pi-ring)] active:opacity-80"
                style={
                  {
                    minHeight: 64,
                    gridTemplateColumns: showIndexNumbers
                      ? "36px minmax(0,1fr) auto"
                      : "minmax(0,1fr) auto",
                    color: t.text,
                    "--pi-ring": `color-mix(in srgb, ${item.accent ?? accent ?? t.accent} 45%, transparent)`,
                  } as CSSProperties
                }
              >
                {showIndexNumbers && (
                  <span
                    className="font-mono text-[11px] tabular-nums"
                    style={{
                      color: open ? ink : t.faint,
                      transition: "color 200ms ease",
                    }}
                  >
                    {pad(i + 1)}
                  </span>
                )}
                <span className="min-w-0">
                  <span className="block truncate text-[19px] font-medium leading-tight tracking-[-0.015em]">
                    {item.title}
                  </span>
                </span>
                <span
                  className="flex items-center gap-3 pl-3 font-mono text-[11px] tabular-nums"
                  style={{ color: t.meta }}
                >
                  {item.year}
                  <span
                    aria-hidden
                    className="relative block size-3"
                    style={{
                      transform: `rotate(${open ? 45 : 0}deg)`,
                      transition: reduce
                        ? "none"
                        : `transform 320ms ${EASE_OUT}`,
                    }}
                  >
                    <span
                      className="absolute left-0 top-1/2 h-px w-3 -translate-y-1/2"
                      style={{ background: "currentColor" }}
                    />
                    <span
                      className="absolute left-1/2 top-0 h-3 w-px -translate-x-1/2"
                      style={{ background: "currentColor" }}
                    />
                  </span>
                </span>
              </button>
              <div
                id={panelId}
                role="region"
                aria-label={item.title}
                className="grid"
                style={{
                  gridTemplateRows: open ? "1fr" : "0fr",
                  transition: reduce
                    ? "none"
                    : `grid-template-rows 320ms ${EASE_OUT}`,
                }}
                inert={!open}
              >
                <div className="min-h-0 overflow-hidden">
                  <div
                    className="pb-5 pt-1"
                    style={{
                      opacity: open ? 1 : 0,
                      transform: open || reduce ? "none" : "translateY(-6px)",
                      transition: reduce
                        ? "opacity 150ms ease"
                        : `opacity 260ms ease ${open ? 80 : 0}ms, transform 320ms ${EASE_OUT}`,
                    }}
                  >
                    <ExpandMedia
                      media={item.media}
                      open={open}
                      reduce={reduce}
                      t={t}
                    />
                    {renderCardBody ? (
                      <div className="mt-4">{renderCardBody(item)}</div>
                    ) : (
                      <dl className="mt-4 grid grid-cols-[88px_minmax(0,1fr)] gap-x-3 gap-y-2 text-[13px] leading-snug">
                        <dt
                          className="font-mono text-[10.5px] uppercase tracking-[0.12em]"
                          style={{ color: t.faint, paddingTop: 2 }}
                        >
                          Role
                        </dt>
                        <dd className="m-0" style={{ color: t.text }}>
                          {item.role}
                        </dd>
                        <dt
                          className="font-mono text-[10.5px] uppercase tracking-[0.12em]"
                          style={{ color: t.faint, paddingTop: 2 }}
                        >
                          Work
                        </dt>
                        <dd className="m-0" style={{ color: t.meta }}>
                          {item.services.join(" / ")}
                        </dd>
                        {item.category && (
                          <>
                            <dt
                              className="font-mono text-[10.5px] uppercase tracking-[0.12em]"
                              style={{ color: t.faint, paddingTop: 2 }}
                            >
                              Kind
                            </dt>
                            <dd className="m-0" style={{ color: t.meta }}>
                              <CategoryMark category={item.category} t={t} />
                            </dd>
                          </>
                        )}
                        {item.outcome && (
                          <>
                            <dt
                              className="font-mono text-[10.5px] uppercase tracking-[0.12em]"
                              style={{ color: t.faint, paddingTop: 6 }}
                            >
                              Outcome
                            </dt>
                            <dd className="m-0 flex items-baseline gap-2">
                              <span
                                className="text-[24px] font-medium leading-none tracking-[-0.03em] tabular-nums"
                                style={{ color: t.text }}
                              >
                                {item.outcome.value}
                              </span>
                              <span style={{ color: t.meta }}>
                                {item.outcome.label}
                              </span>
                            </dd>
                          </>
                        )}
                      </dl>
                    )}
                    {!item.disabled && (
                      <a
                        href={item.href}
                        target={target}
                        rel={target === "_blank" ? "noreferrer" : undefined}
                        tabIndex={open ? 0 : -1}
                        className="mt-5 inline-flex h-10 items-center gap-2 rounded-full px-4 text-[13px] font-medium no-underline outline-none transition-transform duration-150 active:scale-[0.97] focus-visible:shadow-[inset_0_0_0_1px_currentColor]"
                        style={{
                          color: ink,
                          background: `color-mix(in srgb, ${item.accent ?? accent ?? t.accent} ${t.dark ? 14 : 12}%, transparent)`,
                        }}
                      >
                        {openLabel}
                        <span aria-hidden>→</span>
                      </a>
                    )}
                  </div>
                </div>
              </div>
            </motion.li>
          );
        })}
      </ul>
    </GlowRules>
  );
}

/* ------------------------------------------------------------------------------------------------
 * Root
 * ---------------------------------------------------------------------------------------------- */

/**
 * A ledger of work. Titles sit on the left; on hover a dossier card rises from the bottom right
 * and stays put while you move between rows, dissolving its media and swapping only the fields
 * that change. Hairline rules catch a soft light under the pointer. Touch screens get an
 * expanding list instead.
 */
export function ProjectIndex(props: ProjectIndexProps) {
  const {
    items,
    heading,
    tone,
    layout = "auto",
    showCount = true,
    className,
  } = props;
  const resolved = useBjorkTone(tone);
  const t = useMemo(() => tokens(resolved), [resolved]);
  const reduce = useMedia(REDUCED);
  const narrow = useMedia(
    "(hover: none), (pointer: coarse), (max-width: 899px)",
  );
  const expand = layout === "expand" || (layout === "auto" && narrow);

  return (
    <section
      className={cn("relative w-full", className)}
      style={{ color: t.text }}
    >
      {(heading || showCount) && (
        <div className="flex items-baseline justify-between gap-4 px-1 pb-5 md:px-4">
          <div className="min-w-0 text-[15px] font-medium tracking-[-0.01em]">
            {heading}
          </div>
          {showCount && (
            <span
              className="font-mono text-[11px] tabular-nums tracking-[0.08em]"
              style={{ color: t.faint }}
            >
              ({pad(items.length)})
            </span>
          )}
        </div>
      )}
      {expand ? (
        <ExpandIndex {...props} t={t} reduce={reduce} />
      ) : (
        <HoverIndex {...props} t={t} reduce={reduce} />
      )}
    </section>
  );
}

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import {
  BJORK_PALETTE,
  type BjorkTone,
} from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { cn } from "@/lib/utils";

export type GlowRulesAxis = "rows" | "cols" | "grid";

export interface GlowRulesTether {
  /** Centre of the second light, in px from the container's top-left. */
  x: number;
  y: number;
  /** Half-width of the light in px. Default 360. */
  width?: number;
  /** Half-height of the light in px. Default 56. */
  height?: number;
  /** 0 to 1. Default 1. */
  intensity?: number;
}

export interface GlowRulesProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "color"
> {
  children?: ReactNode;
  /** Elements whose edges become rules. Matched inside the container. Default `"li"`. */
  selector?: string;
  /** `rows` draws horizontal rules, `cols` vertical rules, `grid` both. Default `"rows"`. */
  axis?: GlowRulesAxis;
  /** Light size: [half-width as a share of the container, half-height in px]. Default `[0.4, 100]`. */
  radius?: [number, number];
  /** Share of the remaining distance the light covers per 60 Hz frame. Default 0.12. */
  lerp?: number;
  /** Snaps the light to this grid (px) so style writes stay rare. Default 4. */
  quantize?: number;
  /** Light colour. Defaults to white on dark and warm ink on light. */
  color?: string;
  /** Peak opacity of the light, 0 to 1. Default 1 on dark, 0.85 on light. */
  intensity?: number;
  /** Colour of the resting rules. `false` hides them, so the light only shows where you already draw borders. */
  ruleColor?: string | false;
  /** Blend for the light. `auto` uses screen on dark and multiply on light. */
  blend?: "auto" | CSSProperties["mixBlendMode"];
  /** Draw a rule above the first item and below the last. Default true. */
  outerEdges?: boolean;
  /** Keyboard focus inside a matched element moves the light there. Default true. */
  followFocus?: boolean;
  /** A second light pinned to a point, e.g. to lead the eye toward a card. */
  tether?: GlowRulesTether | null;
  /** Draws the rules in from the left the first time they are measured. Default false. */
  drawIn?: boolean;
  /** Turns the light off without unmounting. */
  disabled?: boolean;
  tone?: BjorkTone;
}

export interface GlowRulesHandle {
  /** Re-measures the rules. Call after a change the observers cannot see, such as a transform-free reflow. */
  measure: () => void;
  /** Moves the light to a point (container px) and shows it, as keyboard focus does. */
  pointAt: (x: number, y: number) => void;
  /** Hides the light. */
  release: () => void;
  element: HTMLDivElement | null;
}

const FADE_MS = 350;

function offsetWithin(el: HTMLElement, root: HTMLElement) {
  // offsetTop/Left ignore transforms, so entrance animations on the items do not drag the rules around.
  let x = 0;
  let y = 0;
  let node: HTMLElement | null = el;
  while (node && node !== root) {
    x += node.offsetLeft;
    y += node.offsetTop;
    const parent = node.offsetParent as HTMLElement | null;
    if (!parent || !root.contains(parent)) {
      if (parent !== root) {
        // root is not an offsetParent of this chain: fall back to layout rects.
        const a = el.getBoundingClientRect();
        const b = root.getBoundingClientRect();
        return {
          x: a.left - b.left,
          y: a.top - b.top,
          w: el.offsetWidth,
          h: el.offsetHeight,
        };
      }
    }
    node = parent;
  }
  return { x, y, w: el.offsetWidth, h: el.offsetHeight };
}

function prefersReducedMotion() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

/**
 * Hairline rules that catch a soft light under the pointer. One overlay draws every rule:
 * the rules are 1 px mask layers measured from the matched children, the light is a single
 * radial gradient behind that mask. The pointer is eased and quantised; the loop sleeps when settled.
 */
export const GlowRules = forwardRef<GlowRulesHandle, GlowRulesProps>(
  function GlowRules(
    {
      children,
      selector = "li",
      axis = "rows",
      radius = [0.4, 100],
      lerp = 0.12,
      quantize = 4,
      color,
      intensity,
      ruleColor,
      blend = "auto",
      outerEdges = true,
      followFocus = true,
      tether = null,
      drawIn = false,
      disabled = false,
      tone,
      className,
      style,
      onPointerMove,
      onPointerEnter,
      onPointerLeave,
      onFocus,
      onBlur,
      ...rest
    },
    ref,
  ) {
    const resolved = useBjorkTone(tone);
    const palette = BJORK_PALETTE[resolved];
    const isDark = resolved === "dark";
    const lightColor = color ?? (isDark ? "#ffffff" : "#6b4a2b");
    const peak = intensity ?? (isDark ? 1 : 0.85);
    const rules = ruleColor === undefined ? palette.hair : ruleColor;
    const mixBlend =
      blend === "auto" ? (isDark ? "screen" : "multiply") : blend;

    const rootRef = useRef<HTMLDivElement>(null);
    const layersRef = useRef<HTMLDivElement>(null);
    const glowRef = useRef<HTMLDivElement>(null);
    const tetherRef = useRef<HTMLDivElement>(null);
    const drawnRef = useRef(false);

    // Pointer state lives in refs; React never re-renders for it.
    const state = useRef({
      tx: -9999,
      ty: -9999,
      x: -9999,
      y: -9999,
      lastX: NaN,
      lastY: NaN,
      raf: 0,
      last: 0,
      pointerInside: false,
      focusInside: false,
      snapNext: true,
      // Tether light: eased toward its target in the same loop.
      hx: NaN,
      hy: NaN,
      htx: NaN,
      hty: NaN,
      hLastX: NaN,
      hLastY: NaN,
    });
    const optsRef = useRef({ lerp, quantize });
    useEffect(() => {
      optsRef.current = { lerp, quantize };
    }, [lerp, quantize]);

    const write = useCallback((x: number, y: number) => {
      const el = glowRef.current;
      if (!el) return;
      el.style.setProperty("--gr-x", `${x}px`);
      el.style.setProperty("--gr-y", `${y}px`);
    }, []);

    const tick = useCallback(
      (now: number) => {
        const s = state.current;
        s.raf = 0;
        const dt = s.last ? Math.min(64, now - s.last) : 16.7;
        s.last = now;
        const reduce = prefersReducedMotion();
        const { lerp: l, quantize: q } = optsRef.current;
        const k =
          s.snapNext || reduce
            ? 1
            : 1 - Math.pow(1 - Math.min(1, Math.max(0.001, l)), dt / 16.667);
        s.snapNext = false;
        s.x += (s.tx - s.x) * k;
        s.y += (s.ty - s.y) * k;
        const step = Math.max(1, q);
        const qx = Math.round(s.x / step) * step;
        const qy = Math.round(s.y / step) * step;
        if (qx !== s.lastX || qy !== s.lastY) {
          write(qx, qy);
          s.lastX = qx;
          s.lastY = qy;
        }
        let tetherMoving = false;
        if (!Number.isNaN(s.htx)) {
          if (Number.isNaN(s.hx) || reduce) {
            s.hx = s.htx;
            s.hy = s.hty;
          } else {
            // A touch slower than the pointer light, so the tether trails it.
            const kt = 1 - Math.pow(1 - 0.16, dt / 16.667);
            s.hx += (s.htx - s.hx) * kt;
            s.hy += (s.hty - s.hy) * kt;
          }
          const hx = Math.round(s.hx);
          const hy = Math.round(s.hy);
          if (hx !== s.hLastX || hy !== s.hLastY) {
            tetherRef.current?.style.setProperty("--gt-x", `${hx}px`);
            tetherRef.current?.style.setProperty("--gt-y", `${hy}px`);
            s.hLastX = hx;
            s.hLastY = hy;
          }
          tetherMoving =
            Math.abs(s.htx - s.hx) > 0.5 || Math.abs(s.hty - s.hy) > 0.5;
        }
        if (
          tetherMoving ||
          Math.abs(s.tx - s.x) > 0.5 ||
          Math.abs(s.ty - s.y) > 0.5
        ) {
          s.raf = requestAnimationFrame(tick);
        } else {
          s.last = 0;
        }
      },
      [write],
    );

    const kick = useCallback(() => {
      const s = state.current;
      if (!s.raf) s.raf = requestAnimationFrame(tick);
    }, [tick]);

    const setOn = useCallback(
      (on: boolean) => {
        const el = glowRef.current;
        if (!el) return;
        el.style.opacity = on && !disabled ? String(peak) : "0";
      },
      [disabled, peak],
    );

    const measure = useCallback(() => {
      const root = rootRef.current;
      const layers = layersRef.current;
      if (!root || !layers) return;
      let items: HTMLElement[] = [];
      try {
        items = Array.from(root.querySelectorAll<HTMLElement>(selector)).filter(
          (el) => el.offsetParent !== null || el.getClientRects().length > 0,
        );
      } catch {
        items = [];
      }
      const images: string[] = [];
      const sizes: string[] = [];
      const positions: string[] = [];
      const push = (x: number, y: number, w: number, h: number) => {
        images.push("linear-gradient(#000,#000)");
        sizes.push(`${Math.round(w)}px ${Math.round(h)}px`);
        positions.push(`${Math.round(x)}px ${Math.round(y)}px`);
      };
      const boxes = items.map((el) => offsetWithin(el, root));
      const near = (a: number, b: number) => Math.abs(a - b) <= 1.5;
      const overlapX = (a: (typeof boxes)[number], b: (typeof boxes)[number]) =>
        a.x < b.x + b.w - 1 && b.x < a.x + a.w - 1;
      const overlapY = (a: (typeof boxes)[number], b: (typeof boxes)[number]) =>
        a.y < b.y + b.h - 1 && b.y < a.y + a.h - 1;
      const seen = new Set<string>();
      const line = (x: number, y: number, w: number, h: number) => {
        const key = `${Math.round(x)}:${Math.round(y)}:${Math.round(w)}:${Math.round(h)}`;
        if (seen.has(key)) return;
        seen.add(key);
        push(x, y, w, h);
      };
      if (axis === "rows" || axis === "grid") {
        boxes.forEach((b) => {
          // Top edge, unless it is the outer edge and outer edges are off.
          const hasAbove = boxes.some(
            (o) => o !== b && near(o.y + o.h, b.y) && overlapX(o, b),
          );
          if (outerEdges || hasAbove) line(b.x, b.y, b.w, 1);
          // Bottom edge only where nothing sits directly below, so shared edges draw once.
          const hasBelow = boxes.some(
            (o) => o !== b && near(o.y, b.y + b.h) && overlapX(o, b),
          );
          if (outerEdges && !hasBelow) line(b.x, b.y + b.h - 1, b.w, 1);
        });
      }
      if (axis === "cols" || axis === "grid") {
        boxes.forEach((b) => {
          const hasLeft = boxes.some(
            (o) => o !== b && near(o.x + o.w, b.x) && overlapY(o, b),
          );
          if (outerEdges || hasLeft) line(b.x, b.y, 1, b.h);
          const hasRight = boxes.some(
            (o) => o !== b && near(o.x, b.x + b.w) && overlapY(o, b),
          );
          if (outerEdges && !hasRight) line(b.x + b.w - 1, b.y, 1, b.h);
        });
      }
      const mask = images.length
        ? images.join(",")
        : "linear-gradient(transparent,transparent)";
      layers.style.setProperty("--gr-mask", mask);
      layers.style.setProperty("--gr-mask-size", sizes.join(",") || "0 0");
      layers.style.setProperty("--gr-mask-pos", positions.join(",") || "0 0");
      if (drawIn && !drawnRef.current && images.length) {
        drawnRef.current = true;
        if (!prefersReducedMotion()) {
          layers.animate(
            [
              { clipPath: "inset(0 100% 0 0)" },
              { clipPath: "inset(0 0% 0 0)" },
            ],
            {
              duration: 700,
              easing: "cubic-bezier(0.23,1,0.32,1)",
              fill: "both",
            },
          );
        }
      }
    }, [selector, axis, outerEdges, drawIn]);

    // Measure on size and structure changes. Observing every matched item catches rows that grow.
    useEffect(() => {
      const root = rootRef.current;
      if (!root) return;
      let frame = 0;
      const schedule = () => {
        if (frame) return;
        frame = requestAnimationFrame(() => {
          frame = 0;
          measure();
          observeItems();
        });
      };
      const ro = new ResizeObserver(schedule);
      const observed = new Set<Element>();
      const observeItems = () => {
        let items: Element[] = [];
        try {
          items = Array.from(root.querySelectorAll(selector));
        } catch {
          items = [];
        }
        for (const el of items) {
          if (!observed.has(el)) {
            observed.add(el);
            ro.observe(el);
          }
        }
      };
      ro.observe(root);
      observeItems();
      const mo = new MutationObserver(schedule);
      mo.observe(root, { childList: true, subtree: true });
      schedule();
      if (typeof document !== "undefined" && document.fonts?.ready) {
        document.fonts.ready.then(schedule).catch(() => {});
      }
      return () => {
        if (frame) cancelAnimationFrame(frame);
        ro.disconnect();
        mo.disconnect();
      };
    }, [measure, selector]);

    useEffect(() => {
      const s = state.current;
      return () => {
        if (s.raf) cancelAnimationFrame(s.raf);
      };
    }, []);

    useEffect(() => {
      setOn(state.current.pointerInside || state.current.focusInside);
    }, [setOn]);

    // Tether: keep the last position while it fades out, ease to new positions while it is on.
    const tetherX = tether?.x;
    const tetherY = tether?.y;
    const tetherOn = tether != null && !disabled;
    const tetherAlpha = (tether?.intensity ?? 1) * peak;
    useEffect(() => {
      const el = tetherRef.current;
      if (!el) return;
      const s = state.current;
      if (tetherOn && tetherX != null && tetherY != null) {
        const wasOff = el.style.opacity === "0" || el.style.opacity === "";
        s.htx = tetherX;
        s.hty = tetherY;
        if (wasOff) {
          // Appearing: start in place rather than sliding from the last row.
          s.hx = NaN;
          s.hy = NaN;
        }
        el.style.opacity = String(tetherAlpha);
        kick();
      } else {
        el.style.opacity = "0";
      }
    }, [tetherOn, tetherX, tetherY, tetherAlpha, kick]);

    const pointAt = useCallback(
      (x: number, y: number) => {
        const s = state.current;
        const wasOff = !(s.pointerInside || s.focusInside);
        s.tx = x;
        s.ty = y;
        if (wasOff && s.x < -9000) s.snapNext = true;
        s.focusInside = true;
        setOn(true);
        kick();
      },
      [kick, setOn],
    );

    const release = useCallback(() => {
      state.current.focusInside = false;
      setOn(state.current.pointerInside);
    }, [setOn]);

    useImperativeHandle(
      ref,
      () => ({ measure, pointAt, release, element: rootRef.current }),
      [measure, pointAt, release],
    );

    // Works inside scaled parents: layout px = screen px / scale.
    const toLocal = (clientX: number, clientY: number) => {
      const el = rootRef.current!;
      const r = el.getBoundingClientRect();
      const sx = el.offsetWidth ? r.width / el.offsetWidth : 1;
      const sy = el.offsetHeight ? r.height / el.offsetHeight : 1;
      return {
        x: (clientX - r.left) / (sx || 1),
        y: (clientY - r.top) / (sy || 1),
      };
    };

    const [rx, ry] = radius;
    const glowBg = `radial-gradient(ellipse ${Math.max(1, rx * 100)}% ${ry}px at var(--gr-x, -9999px) var(--gr-y, -9999px), ${lightColor} 0%, color-mix(in srgb, ${lightColor} 55%, transparent) 38%, transparent 100%)`;
    const tetherBg = `radial-gradient(ellipse ${tether?.width ?? 360}px ${tether?.height ?? 56}px at var(--gt-x, -9999px) var(--gt-y, -9999px), ${lightColor} 0%, color-mix(in srgb, ${lightColor} 40%, transparent) 45%, transparent 100%)`;

    const maskStyle: CSSProperties = {
      WebkitMaskImage: "var(--gr-mask)",
      maskImage: "var(--gr-mask)",
      WebkitMaskSize: "var(--gr-mask-size)",
      maskSize: "var(--gr-mask-size)",
      WebkitMaskPosition: "var(--gr-mask-pos)",
      maskPosition: "var(--gr-mask-pos)",
      WebkitMaskRepeat: "no-repeat",
      maskRepeat: "no-repeat",
    };

    return (
      <div
        ref={rootRef}
        className={cn("relative", className)}
        style={style}
        data-glow-rules=""
        onPointerMove={(e) => {
          onPointerMove?.(e);
          if (disabled || e.pointerType === "touch") return;
          const s = state.current;
          const p = toLocal(e.clientX, e.clientY);
          s.tx = p.x;
          s.ty = p.y;
          if (!s.pointerInside) {
            s.pointerInside = true;
            // First contact: start the light under the pointer instead of sweeping in from the last spot.
            if (!s.focusInside) s.snapNext = true;
            setOn(true);
          }
          kick();
        }}
        onPointerEnter={(e) => {
          onPointerEnter?.(e);
          if (disabled || e.pointerType === "touch") return;
          const s = state.current;
          const p = toLocal(e.clientX, e.clientY);
          s.tx = p.x;
          s.ty = p.y;
          s.pointerInside = true;
          if (!s.focusInside) s.snapNext = true;
          setOn(true);
          kick();
        }}
        onPointerLeave={(e) => {
          onPointerLeave?.(e);
          state.current.pointerInside = false;
          setOn(state.current.focusInside);
        }}
        onFocus={(e) => {
          onFocus?.(e);
          if (!followFocus || disabled) return;
          const target = e.target as HTMLElement;
          let item: HTMLElement | null = null;
          try {
            item = target.closest<HTMLElement>(selector);
          } catch {
            item = null;
          }
          if (!item || !rootRef.current?.contains(item)) return;
          if (!target.matches(":focus-visible")) return;
          const b = offsetWithin(item, rootRef.current);
          // Light the left third of the item, where the eye starts reading.
          pointAt(b.x + Math.min(b.w * 0.3, 320), b.y + b.h / 2);
        }}
        onBlur={(e) => {
          onBlur?.(e);
          const next = e.relatedTarget as Node | null;
          if (next && rootRef.current?.contains(next)) return;
          release();
        }}
        {...rest}
      >
        {children}
        <div
          ref={layersRef}
          aria-hidden
          className="pointer-events-none absolute inset-0"
          style={{ zIndex: 1 }}
        >
          {rules !== false && (
            <div
              className="absolute inset-0"
              style={{ ...maskStyle, background: rules }}
            />
          )}
          <div
            ref={glowRef}
            className="absolute inset-0"
            style={{
              ...maskStyle,
              background: glowBg,
              mixBlendMode: mixBlend,
              opacity: 0,
              transition: `opacity ${FADE_MS}ms ease`,
            }}
          />
          <div
            ref={tetherRef}
            className="absolute inset-0"
            style={{
              ...maskStyle,
              background: tetherBg,
              mixBlendMode: mixBlend,
              opacity: 0,
              transition: `opacity ${FADE_MS}ms ease`,
            }}
          />
        </div>
      </div>
    );
  },
);

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

// Media stage for Project Index: one WebGL canvas that dissolves between images and videos.
// No dependencies. Falls back (create() returns null) when WebGL is unavailable.

export interface StageMedia {
  type: "image" | "video";
  src: string;
  poster?: string;
  focal?: [number, number];
}

interface Tex {
  tex: WebGLTexture;
  w: number;
  h: number;
  focal: [number, number];
  /** Canvas-space buffer: no cover fitting. */
  screen?: boolean;
}

interface VideoEntry {
  el: HTMLVideoElement;
  tex: WebGLTexture;
  ready: boolean;
  fresh: boolean;
  used: number;
}

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

// Grain dissolve. The front sweeps in the direction of travel, broken up by a low-frequency
// fbm and a fine sand grain; pixels near the front are pushed along the sweep and lifted a touch.
const FRAG = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uA;
uniform sampler2D uB;
uniform vec4 uFitA; // xy scale, zw offset
uniform vec4 uFitB;
uniform float uP;
uniform float uDir;
uniform float uSeed;
uniform float uTime;
uniform float uZoom;
uniform vec2 uRes;
uniform float uGrain;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p *= 2.03;
    a *= 0.5;
  }
  return v;
}
vec3 sampleFit(sampler2D t, vec4 fit, vec2 uv) {
  vec2 c = (uv - 0.5) / uZoom + 0.5;
  vec2 st = c * fit.xy + fit.zw;
  return texture2D(t, clamp(st, 0.0, 1.0)).rgb;
}
void main() {
  vec2 uv = vUv;
  float p = uP;
  // Low-frequency shape of the front plus fine grain in device pixels (about 2 px sand).
  float n = fbm(uv * vec2(3.0, 5.0) + uSeed);
  float g = hash(floor(uv * uRes / 2.0) + uSeed * 31.0);
  float along = uDir > 0.0 ? uv.y : 1.0 - uv.y;    // 0 where the new media enters
  float edge = along * 0.72 + n * 0.2 + g * 0.08;
  float m = p * 1.24 - 0.12;
  float t = smoothstep(edge - 0.06, edge + 0.06, m);
  // Grains just ahead of the front fall in early, like sand ahead of a wave.
  // ahead: 0 far in front of the front, 1 at the front itself.
  float ahead = smoothstep(edge - 0.1, edge, m);
  float scatter = step(g, ahead * ahead * 0.5);
  t = max(t, scatter);
  float front = smoothstep(0.22, 0.0, abs(m - edge));
  vec2 push = vec2(0.0, -uDir) * 0.035 * front * (n - 0.35);
  vec3 a = sampleFit(uA, uFitA, uv + push * t);
  vec3 b = sampleFit(uB, uFitB, uv - push * (1.0 - t));
  vec3 col = mix(a, b, t);
  // A faint lift along the front, and film grain that only lives during the move.
  col += front * 0.06 * (1.0 - abs(p * 2.0 - 1.0));
  float live = sin(p * 3.14159);
  col += (hash(uv * uRes + floor(uTime * 24.0)) - 0.5) * 0.07 * live * uGrain;
  gl_FragColor = vec4(col, 1.0);
}`;

function compile(gl: WebGLRenderingContext, type: number, src: string) {
  const sh = gl.createShader(type)!;
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(sh);
    gl.deleteShader(sh);
    throw new Error(log ?? "shader");
  }
  return sh;
}

function program(gl: WebGLRenderingContext, frag: string) {
  const p = gl.createProgram()!;
  gl.attachShader(p, compile(gl, gl.VERTEX_SHADER, VERT));
  gl.attachShader(p, compile(gl, gl.FRAGMENT_SHADER, frag));
  gl.bindAttribLocation(p, 0, "aPos");
  gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS))
    throw new Error(gl.getProgramInfoLog(p) ?? "link");
  return p;
}

const easeInOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

export class MediaStage {
  private gl: WebGLRenderingContext;
  private prog: WebGLProgram;
  private u: Record<string, WebGLUniformLocation | null> = {};
  private images = new Map<string, Promise<Tex>>();
  private videos = new Map<string, VideoEntry>();
  private fbos: { fb: WebGLFramebuffer; tex: WebGLTexture }[] = [];
  private fboIndex = 0;
  private a: Tex | null = null;
  private b: Tex | null = null;
  private bVideo: VideoEntry | null = null;
  private aVideo: VideoEntry | null = null;
  private progress = 1;
  private dir = 1;
  private seed = 0;
  private start = 0;
  private token = 0;
  private dirty = true;
  zoom = 1;
  duration = 420;
  maxVideos = 3;

  static create(canvas: HTMLCanvasElement): MediaStage | null {
    try {
      const gl = canvas.getContext("webgl", {
        alpha: false,
        antialias: false,
        premultipliedAlpha: false,
        preserveDrawingBuffer: false,
      });
      if (!gl) return null;
      return new MediaStage(canvas, gl);
    } catch {
      return null;
    }
  }

  private constructor(
    private canvas: HTMLCanvasElement,
    gl: WebGLRenderingContext,
  ) {
    this.gl = gl;
    this.prog = program(gl, FRAG);
    for (const name of [
      "uA",
      "uB",
      "uFitA",
      "uFitB",
      "uP",
      "uDir",
      "uSeed",
      "uTime",
      "uZoom",
      "uRes",
      "uGrain",
    ]) {
      this.u[name] = gl.getUniformLocation(this.prog, name);
    }
    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
      gl.STATIC_DRAW,
    );
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  }

  resize(w: number, h: number) {
    if (this.canvas.width === w && this.canvas.height === h) return;
    this.canvas.width = w;
    this.canvas.height = h;
    // Old buffers are the wrong size now.
    const gl = this.gl;
    for (const f of this.fbos) {
      gl.deleteFramebuffer(f.fb);
      gl.deleteTexture(f.tex);
    }
    this.fbos = [];
    if (this.a?.screen) this.a = this.b;
    this.dirty = true;
  }

  private newTexture() {
    const gl = this.gl;
    const tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      1,
      1,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      new Uint8Array([0, 0, 0, 255]),
    );
    return tex;
  }

  loadImage(src: string, focal: [number, number] = [0.5, 0.5]): Promise<Tex> {
    const key = src;
    const hit = this.images.get(key);
    if (hit) return hit.then((t) => ({ ...t, focal }));
    const p = new Promise<Tex>((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.decoding = "async";
      img.onload = () => {
        const gl = this.gl;
        const tex = this.newTexture();
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGBA,
          gl.RGBA,
          gl.UNSIGNED_BYTE,
          img,
        );
        resolve({ tex, w: img.naturalWidth, h: img.naturalHeight, focal });
      };
      img.onerror = () => reject(new Error(`image ${src}`));
      img.src = src;
    });
    p.catch(() => this.images.delete(key));
    this.images.set(key, p);
    return p;
  }

  /** Warms the cache without showing anything. */
  preload(media: StageMedia) {
    const still = media.type === "image" ? media.src : media.poster;
    if (still) this.loadImage(still).catch(() => {});
  }

  private videoFor(media: StageMedia): VideoEntry {
    const v = this.videos.get(media.src);
    if (v) {
      v.used = performance.now();
      return v;
    }
    const el = document.createElement("video");
    el.muted = true;
    el.loop = true;
    el.playsInline = true;
    el.crossOrigin = "anonymous";
    el.preload = "auto";
    el.setAttribute("muted", "");
    el.setAttribute("playsinline", "");
    el.src = media.src;
    const entry: VideoEntry = {
      el,
      tex: this.newTexture(),
      ready: false,
      fresh: false,
      used: performance.now(),
    };
    const onFrame = () => {
      entry.ready = true;
      entry.fresh = true;
      this.dirty = true;
      const rvfc = (
        el as HTMLVideoElement & {
          requestVideoFrameCallback?: (cb: () => void) => number;
        }
      ).requestVideoFrameCallback;
      if (rvfc) rvfc.call(el, onFrame);
    };
    const rvfc = (
      el as HTMLVideoElement & {
        requestVideoFrameCallback?: (cb: () => void) => number;
      }
    ).requestVideoFrameCallback;
    if (rvfc) rvfc.call(el, onFrame);
    else el.addEventListener("timeupdate", onFrame);
    this.videos.set(media.src, entry);
    // Keep at most maxVideos alive, dropping the least recently used that is not on screen.
    if (this.videos.size > this.maxVideos) {
      const victims = [...this.videos.entries()]
        .filter(
          ([, e]) => e !== this.bVideo && e !== this.aVideo && e !== entry,
        )
        .sort((x, y) => x[1].used - y[1].used);
      const [key, victim] = victims[0] ?? [];
      if (key && victim) {
        victim.el.pause();
        victim.el.removeAttribute("src");
        victim.el.load();
        this.gl.deleteTexture(victim.tex);
        this.videos.delete(key);
      }
    }
    return entry;
  }

  private fit(t: Tex): [number, number, number, number] {
    if (t.screen) return [1, 1, 0, 0];
    const cw = this.canvas.width;
    const ch = this.canvas.height;
    const ca = cw / Math.max(1, ch);
    const ta = t.w / Math.max(1, t.h);
    let sx = 1;
    let sy = 1;
    if (ta > ca) sx = ca / ta;
    else sy = ta / ca;
    const [fx, fy] = t.focal;
    // Offset toward the focal point (focal y is top-down; texture space is bottom-up).
    const ox = (1 - sx) * fx;
    const oy = (1 - sy) * (1 - fy);
    return [sx, sy, ox, oy];
  }

  /** Captures what is on screen into a buffer so a new transition can start from it. */
  private snapshot(time: number): Tex | null {
    const gl = this.gl;
    const w = this.canvas.width;
    const h = this.canvas.height;
    if (!this.fbos.length) {
      for (let i = 0; i < 2; i++) {
        const tex = this.newTexture();
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGBA,
          w,
          h,
          0,
          gl.RGBA,
          gl.UNSIGNED_BYTE,
          null,
        );
        const fb = gl.createFramebuffer()!;
        gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
        gl.framebufferTexture2D(
          gl.FRAMEBUFFER,
          gl.COLOR_ATTACHMENT0,
          gl.TEXTURE_2D,
          tex,
          0,
        );
        this.fbos.push({ fb, tex });
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    }
    // Never render into the buffer we are reading from.
    let slot = this.fbos[this.fboIndex];
    if (this.a?.tex === slot.tex) {
      this.fboIndex = 1 - this.fboIndex;
      slot = this.fbos[this.fboIndex];
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, slot.fb);
    this.draw(time, true);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    this.fboIndex = 1 - this.fboIndex;
    return { tex: slot.tex, w, h, focal: [0.5, 0.5], screen: true };
  }

  /**
   * Shows media. `dir` is +1 when moving down the list and -1 when moving up.
   * `instant` swaps without a transition (first open, reduced motion).
   */
  async show(media: StageMedia, dir: number, instant: boolean) {
    const token = ++this.token;
    const focal = media.focal ?? [0.5, 0.5];
    let next: Tex | null = null;
    let video: VideoEntry | null = null;
    if (media.type === "video") {
      video = this.videoFor(media);
      video.el.play().catch(() => {});
      if (video.ready)
        next = {
          tex: video.tex,
          w: video.el.videoWidth,
          h: video.el.videoHeight,
          focal,
        };
      else if (media.poster)
        next = await this.loadImage(media.poster, focal).catch(() => null);
      if (!next) {
        // No poster and no frame yet: wait for the first frame.
        await new Promise<void>((res) => {
          const done = () => res();
          video!.el.addEventListener("loadeddata", done, { once: true });
          setTimeout(done, 1500);
        });
        next = {
          tex: video.tex,
          w: video.el.videoWidth || 16,
          h: video.el.videoHeight || 10,
          focal,
        };
      }
    } else {
      next = await this.loadImage(media.src, focal).catch(() => null);
    }
    if (token !== this.token || !next) return;

    // Pause the video we are leaving once it is no longer needed.
    const leaving = this.bVideo;
    const now = performance.now();
    if (instant || !this.b) {
      this.a = null;
      this.b = next;
      this.aVideo = null;
      this.bVideo = video;
      this.progress = 1;
    } else {
      const inFlight = this.progress < 1;
      this.a = inFlight ? this.snapshot(now) : this.b;
      this.aVideo = inFlight ? null : leaving;
      this.b = next;
      this.bVideo = video;
      this.dir = dir >= 0 ? 1 : -1;
      this.seed = Math.random() * 10;
      this.progress = 0;
      this.start = now;
    }
    if (leaving && leaving !== video && leaving !== this.aVideo)
      leaving.el.pause();
    this.dirty = true;
  }

  pauseVideos() {
    for (const v of this.videos.values()) v.el.pause();
  }

  resumeVideo() {
    this.bVideo?.el.play().catch(() => {});
  }

  get transitioning() {
    return this.progress < 1;
  }

  /** True while there is a reason to keep drawing. */
  get busy() {
    return (
      this.progress < 1 ||
      this.dirty ||
      (!!this.bVideo && !this.bVideo.el.paused)
    );
  }

  private upload(v: VideoEntry | null) {
    if (!v || !v.fresh || v.el.readyState < 2) return;
    const gl = this.gl;
    gl.bindTexture(gl.TEXTURE_2D, v.tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, v.el);
    v.fresh = false;
  }

  /** Draws a frame. Returns true while it needs more frames. */
  frame(time: number): boolean {
    if (!this.b) return false;
    if (this.progress < 1) {
      this.progress = Math.min(1, (time - this.start) / this.duration);
      if (this.progress >= 1) {
        if (this.aVideo && this.aVideo !== this.bVideo) this.aVideo.el.pause();
        this.a = null;
        this.aVideo = null;
      }
      // Every step of a transition draws, including the one that lands on 1.
      this.dirty = true;
    }
    // Swap the poster for live video once the first frame exists.
    if (this.bVideo?.ready && this.b.tex !== this.bVideo.tex) {
      this.b = {
        tex: this.bVideo.tex,
        w: this.bVideo.el.videoWidth,
        h: this.bVideo.el.videoHeight,
        focal: this.b.focal,
      };
    }
    const videoFresh = !!(this.bVideo?.fresh || this.aVideo?.fresh);
    if (!this.dirty && this.progress >= 1 && !videoFresh) return this.busy;
    this.upload(this.bVideo);
    this.upload(this.aVideo);
    this.draw(time, false);
    this.dirty = false;
    return this.busy;
  }

  markDirty() {
    this.dirty = true;
  }

  private draw(time: number, toBuffer: boolean) {
    const gl = this.gl;
    const b = this.b!;
    const a = this.a ?? b;
    const p = this.a ? easeInOut(this.progress) : 1;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.useProgram(this.prog);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, a.tex);
    gl.uniform1i(this.u.uA, 0);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, b.tex);
    gl.uniform1i(this.u.uB, 1);
    gl.uniform4fv(this.u.uFitA, this.fit(a));
    gl.uniform4fv(this.u.uFitB, this.fit(b));
    gl.uniform1f(this.u.uP, p);
    gl.uniform1f(this.u.uDir, this.dir);
    gl.uniform1f(this.u.uSeed, this.seed);
    gl.uniform1f(this.u.uTime, time / 1000);
    gl.uniform1f(this.u.uZoom, this.zoom);
    gl.uniform2f(this.u.uRes, this.canvas.width, this.canvas.height);
    gl.uniform1f(this.u.uGrain, toBuffer ? 0 : 1);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }

  dispose() {
    this.token++;
    const gl = this.gl;
    for (const v of this.videos.values()) {
      v.el.pause();
      v.el.removeAttribute("src");
      v.el.load();
      gl.deleteTexture(v.tex);
    }
    this.videos.clear();
    for (const p of this.images.values())
      p.then((t) => gl.deleteTexture(t.tex)).catch(() => {});
    this.images.clear();
    for (const f of this.fbos) {
      gl.deleteFramebuffer(f.fb);
      gl.deleteTexture(f.tex);
    }
    gl.getExtension("WEBGL_lose_context")?.loseContext();
  }
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

